Fixes: 37dd0247797b1 ("gue: Receive side for Generic UDP Encapsulation")
Reported-by: syzbot+4d8c7d16b0e95c0d0f0d@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/netdev/6965534b.050a0220.38aacd.0001.GAE@google.com/
Signed-off-by: Kuniyuki Iwashima <kuniyu@google.com>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Link: https://patch.msgid.link/20260115172533.693652-2-kuniyu@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The gue_udp_recv() function returns -guehdr->proto_ctype to indicate a resubmit, but when proto_ctype is 0, the return value is 0 (since -0 == 0), which is treated as success by the caller, causing the skb to be leaked.

Here is the patch:

 static int gue_udp_recv(struct sock *sk, struct sk_buff *skb)
 {
 	struct fou *fou = fou_from_sock(sk);
 	size_t len, optlen, hdrlen;
 	struct guehdr *guehdr;
 	void *data;
 	u16 doffset = 0;
 	u8 proto_ctype;

 	if (!fou)
 		return 1;

 	len = sizeof(struct udphdr) + sizeof(struct guehdr);
 	if (!pskb_may_pull(skb, len))
 		goto drop;

 	guehdr = (struct guehdr *)&udp_hdr(skb)[1];

 	switch (guehdr->version) {
 	case 0: /* Full GUE header present */
 		break;

 	case 1: {
 		/* Direct encapsulation of IPv4 or IPv6 */

 		int prot;

 		switch (((struct iphdr *)guehdr)->version) {
 		case 4:
 			prot = IPPROTO_IPIP;
 			break;
 		case 6:
 			prot = IPPROTO_IPV6;
 			break;
 		default:
 			goto drop;
 		}

 		if (fou_recv_pull(skb, fou, sizeof(struct udphdr)))
 			goto drop;

 		return -prot;
 	}

 	default: /* Undefined version */
 		goto drop;
 	}

 	optlen = guehdr->hlen << 2;
 	len += optlen;

 	if (!pskb_may_pull(skb, len))
 		goto drop;

 	/* guehdr may change after pull */
 	guehdr = (struct guehdr *)&udp_hdr(skb)[1];

 	if (validate_gue_flags(guehdr, optlen))
 		goto drop;

 	hdrlen = sizeof(struct guehdr) + optlen;

 	if (fou->family == AF_INET)
 		ip_hdr(skb)->tot_len = htons(ntohs(ip_hdr(skb)->tot_len) - len);
 	else
 		ipv6_hdr(skb)->payload_len =
 		    htons(ntohs(ipv6_hdr(skb)->payload_len) - len);

 	/* Pull csum through the guehdr now . This can be used if
 	 * there is a remote checksum offload.
 	 */
 	skb_postpull_rcsum(skb, udp_hdr(skb), len);

 	data = &guehdr[1];

 	if (guehdr->flags & GUE_FLAG_PRIV) {
 		__be32 flags = *(__be32 *)(data + doffset);

 		doffset += GUE_LEN_PRIV;

 		if (flags & GUE_PFLAG_REMCSUM) {
 			guehdr = gue_remcsum(skb, guehdr, data + doffset,
 					     hdrlen, guehdr->proto_ctype,
 					     !!(fou->flags &
 						FOU_F_REMCSUM_NOPARTIAL));
 			if (!guehdr)
 				goto drop;

 			data = &guehdr[1];

 			doffset += GUE_PLEN_REMCSUM;
 		}
 	}

 	if (unlikely(guehdr->control))
 		return gue_control_message(skb, guehdr);

 	proto_ctype = guehdr->proto_ctype;
+	if (unlikely(!proto_ctype))
+		goto drop;
+
 	__skb_pull(skb, sizeof(struct udphdr) + hdrlen);
 	skb_reset_transport_header(skb);

 	if (iptunnel_pull_offloads(skb))
 		goto drop;

 	return -proto_ctype;

 drop:
 	kfree_skb(skb);
 	return 0;
 }



